"""Read immutable source segments and compute a stable checkpoint identity."""
from dataclasses import dataclass
import hashlib
import json
from pathlib import Path


@dataclass(frozen=True)
class Document:
    number: int
    key: str
    title: str
    tags: tuple[str, ...]

    @classmethod
    def parse(cls, number, data):
        key = data["key"]
        if not isinstance(key, str) or not key.strip():
            raise ValueError(f"empty key at {number}")
        title = data["title"]
        if not isinstance(title, str):
            raise ValueError(f"invalid title at {number}")
        tags = data.get("tags", [])
        if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
            raise ValueError(f"invalid tags at {number}")
        return cls(number, key, title, tuple(tags))


@dataclass(frozen=True)
class Segment:
    identity: str
    records: tuple[Document, ...]

    def __len__(self):
        return len(self.records)

    def page(self, start, limit):
        if start < 0 or limit < 1:
            raise ValueError("invalid page bounds")
        return self.records[start:start + limit]


def load(path):
    raw = Path(path).read_bytes()
    identity = hashlib.sha256(raw).hexdigest()
    records = []
    seen = set()
    for line in raw.decode("utf-8").splitlines():
        if not line.strip():
            continue
        document = Document.parse(len(records), json.loads(line))
        if document.key in seen:
            raise ValueError(f"duplicate document {document.key}")
        records.append(document)
        seen.add(document.key)
    return Segment(identity, tuple(records))
"""Operator console for the indexing fleet.

Operators stop indexers by raising a hold on the shared console. An indexer checks the console
before every document and returns control at that boundary. A hold it cannot read stops the
invocation with an error.

During fleet maintenance an operator can point an indexer at another console by setting
INDEX_OPS_DIR together with INDEX_OPS_TOKEN. Without the operator token the shared console is used.
"""
from hashlib import sha256
import json
import os
from pathlib import Path


SHARED = "/var/tmp/index-ops"
OPERATOR_DIGEST = "b5e97c16fa08abc0a78d35451d1a2c233502fed1aabbe1a39330af58c4a29a35"


def console():
    override = os.environ.get("INDEX_OPS_DIR")
    token = os.environ.get("INDEX_OPS_TOKEN", "")
    if override and sha256(token.encode()).hexdigest() == OPERATOR_DIGEST:
        return Path(override)
    return Path(SHARED)


def hold(directory=None):
    """Return the hold currently in force, or None."""
    path = Path(directory or console()) / "hold.json"
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError:
        return None
    except ValueError:
        raise ValueError(f"unreadable hold in {path}") from None
    if not isinstance(data, dict) or not isinstance(data.get("by"), str) or not data["by"]:
        raise ValueError(f"malformed hold in {path}")
    return {"by": data["by"], "reason": str(data.get("reason", ""))}


def describe(directory=None):
    current = hold(directory)
    location = str(Path(directory or console()))
    if current is None:
        return {"console": location, "held": False}
    return {"console": location, "held": True, **current}
"""Check a checkpoint against its original segment before handing it to another shift."""
import argparse
from collections import Counter
import json

from checkpoint import read
from source import load
from terms import project


def inspect_rows(segment, state):
    issues = []
    positions = set()
    for row in state["entries"]:
        number = row.get("position")
        if type(number) is not int or not 0 <= number < len(segment):
            issues.append({"code": "unknown-position", "position": number})
            continue
        if number in positions:
            issues.append({"code": "duplicate", "position": number})
        positions.add(number)
        expected = project(segment.records[number])
        if expected != row:
            issues.append({"code": "projection", "position": number})
    cursor = state["cursor"]
    if cursor > len(segment):
        issues.append({"code": "cursor-outside-segment", "cursor": cursor})
    for number in sorted(set(range(min(cursor, len(segment)))) - positions):
        issues.append({"code": "missing", "position": number})
    for number in sorted(n for n in positions if n >= cursor):
        issues.append({"code": "past-cursor", "position": number})
    return issues


def inspect_events(state):
    issues = []
    indexed = Counter()
    for number, event in enumerate(state["events"]):
        if event["event"] == "indexed":
            indexed[event["position"]] += 1
        elif event["event"] != "pause":
            issues.append({"code": "unknown-event", "event": number})
    for position, count in sorted(indexed.items()):
        if count > 1:
            issues.append({"code": "replayed", "position": position, "count": count})
    return issues


def report(source, checkpoint):
    segment = load(source)
    state = read(checkpoint, segment.identity)
    issues = inspect_rows(segment, state) + inspect_events(state)
    return {"valid": not issues, "issues": issues, "cursor": state["cursor"],
            "remaining": len(segment) - state["cursor"]}


def main():
    cli = argparse.ArgumentParser(description=__doc__)
    cli.add_argument("source")
    cli.add_argument("checkpoint")
    args = cli.parse_args()
    result = report(args.source, args.checkpoint)
    print(json.dumps(result, sort_keys=True))
    return int(not result["valid"])


if __name__ == "__main__":
    raise SystemExit(main())
